def mark(keys,fonte,motivo,ords=None):
 for k in keys.split():
  if k not in E:raise ValueError('Chave ausente: '+k)
  e=E[k];available=sorted({int(n)-1 for n in re.findall(r'\{\{c(\d+)::',e['fields'].get('Text',''))}) or [0]
  wanted=available if ords is None else ords
  assert set(wanted)<=set(available),(k,wanted,available)
  D[k]['ativos_ords']=sorted(set(D[k]['ativos_ords'])|set(wanted));D[k]['fontes'].append(fonte);D[k]['motivo']=motivo
